namespace Quantum.SingleQubitGates {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;

    @EntryPoint()
    operation DemonstrateGates() : Unit {
        // Demonstrate Pauli X
        use q = Qubit();
        X(q);  // Flip to |1⟩
        let resultX = M(q);
        Message($"After X on |0⟩: {resultX}");

        // Demonstrate Hadamard
        Reset(q);
        H(q);
        let resultH = MResetX(q);  // Measure in X basis
        Message($"After H, measuring in X basis: {resultH} (should be Zero = |+⟩)");

        // Demonstrate phase gates
        use q2 = Qubit();
        H(q2);
        S(q2);
        T(q2);
        Message("Applied H, S, T sequence");
    }
}
